import{_ as t,c as r,o as e,ag as l}from"./chunks/framework.CMajxlqO.js";const m=JSON.parse('{"title":"Globala vs lokala taggar","description":"","frontmatter":{},"headers":[],"relativePath":"05-taggar/globala-lokala-FULL.md","filePath":"05-taggar/globala-lokala-FULL.md","lastUpdated":1768460368000}'),o={name:"05-taggar/globala-lokala-FULL.md"};function n(d,a,s,i,g,c){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="globala-vs-lokala-taggar" tabindex="-1">Globala vs lokala taggar <a class="header-anchor" href="#globala-vs-lokala-taggar" aria-label="Permalink to &quot;Globala vs lokala taggar&quot;">​</a></h1><p>I TIA Portal använder du <strong>taggar</strong> (variabler) för att lagra data och kommunicera mellan olika delar av programmet. Att förstå skillnaden mellan globala och lokala taggar är avgörande för att strukturera ditt program korrekt.</p><h2 id="vad-ar-taggar" tabindex="-1">Vad är taggar? <a class="header-anchor" href="#vad-ar-taggar" aria-label="Permalink to &quot;Vad är taggar?&quot;">​</a></h2><p>Taggar är <strong>symboliska namn</strong> för minnesområden. Istället för <code>%M0.0</code> kan du använda <code>Motor_Start</code>.</p><h3 id="fordelar" tabindex="-1">Fördelar: <a class="header-anchor" href="#fordelar" aria-label="Permalink to &quot;Fördelar:&quot;">​</a></h3><ul><li>✅ <strong>Läsbar</strong> kod</li><li>✅ <strong>Enklare underhåll</strong></li><li>✅ <strong>HMI-integration</strong></li></ul><h2 id="globala-taggar-plc-tags" tabindex="-1">Globala taggar (PLC Tags) <a class="header-anchor" href="#globala-taggar-plc-tags" aria-label="Permalink to &quot;Globala taggar (PLC Tags)&quot;">​</a></h2><p><strong>Tillgängliga överallt</strong> - från alla OB, FB, FC och HMI.</p><h3 id="anvandning" tabindex="-1">Användning: <a class="header-anchor" href="#anvandning" aria-label="Permalink to &quot;Användning:&quot;">​</a></h3><ul><li>In/utgångar (<code>%I</code>, <code>%Q</code>)</li><li>Systemvariabler</li><li>HMI-kommunikation</li></ul><h3 id="exempel" tabindex="-1">Exempel: <a class="header-anchor" href="#exempel" aria-label="Permalink to &quot;Exempel:&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Namn</th><th>Typ</th><th>Adress</th><th>Kommentar</th></tr></thead><tbody><tr><td><code>Start_Button</code></td><td>BOOL</td><td>%I0.0</td><td>Startknapp</td></tr><tr><td><code>Motor_Output</code></td><td>BOOL</td><td>%Q0.0</td><td>Motorutgång</td></tr></tbody></table><h2 id="lokala-taggar" tabindex="-1">Lokala taggar <a class="header-anchor" href="#lokala-taggar" aria-label="Permalink to &quot;Lokala taggar&quot;">​</a></h2><p><strong>Endast inom ett block</strong> (FB/FC/OB).</p><h3 id="typer" tabindex="-1">Typer: <a class="header-anchor" href="#typer" aria-label="Permalink to &quot;Typer:&quot;">​</a></h3><ul><li><strong>VAR_INPUT</strong> - Parametrar in</li><li><strong>VAR_OUTPUT</strong> - Resultat ut</li><li><strong>VAR</strong> - Static (FB), behålls mellan anrop</li><li><strong>VAR_TEMP</strong> - Temporära, nollställs varje cykel</li></ul><h2 id="jamforelse" tabindex="-1">Jämförelse <a class="header-anchor" href="#jamforelse" aria-label="Permalink to &quot;Jämförelse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Egenskap</th><th>Globala</th><th>Lokala</th></tr></thead><tbody><tr><td>Synlighet</td><td>Hela programmet</td><td>Endast inom block</td></tr><tr><td>HMI-access</td><td>Ja</td><td>Nej</td></tr><tr><td>Livslängd</td><td>Permanent</td><td>Temp/Static</td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><p>✅ Använd <strong>PascalCase</strong> eller <strong>Snake_Case</strong> ✅ Tydliga namn: <code>Emergency_Stop</code> inte <code>ES</code> ❌ Undvik: <code>m1</code>, <code>temp</code>, <code>x</code></p><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/document/36932465" target="_blank" rel="noreferrer">S7-1200 Tags Documentation</a></li><li>YouTube: &quot;TIA Portal tags tutorial&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Lär dig mer om <a href="./datatyper.html">Datatyper</a>!</p></div>',23)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
